218	// CreateEntry creates or replaces an entry. When existing is non-nil the caller
219	// has already fetched the current entry at this path under a path lock, and it
220	// is reused instead of looking the store up again; pass nil to have CreateEntry
221	// look it up itself.
222	func (f *Filer) CreateEntry(ctx context.Context, entry *Entry, existing *Entry, o_excl bool, isFromOtherCluster bool, signatures []int32, skipCreateParentDir bool, maxFilenameLength uint32) error {
223	
224		if string(entry.FullPath) == "/" {
225			return nil
226		}
227	
228		if entry.FullPath.IsLongerFileName(maxFilenameLength) {
229			return filer_pb.ErrEntryNameTooLong
230		}
231	
232		if entry.IsDirectory() {
233			entry.Attr.TtlSec = 0
234		}
235	
236		if entry.Attr.Atime.IsZero() {
237			entry.Attr.Atime = entryInitialAtime(entry.Attr)
238		}
239	
240		oldEntry := existing
241		if oldEntry == nil {
242			oldEntry, _ = f.FindEntry(ctx, entry.FullPath)
243		}
244	
245		/*
246			if !hasWritePermission(lastDirectoryEntry, entry) {
247				glog.V(0).Infof("directory %s: %v, entry: uid=%d gid=%d",
248					lastDirectoryEntry.FullPath, lastDirectoryEntry.Attr, entry.Uid, entry.Gid)
249				return fmt.Errorf("no write permission in folder %v", lastDirectoryEntry.FullPath)
250			}
251		*/
252	
253		if oldEntry == nil {
254			f.ensureEntryInode(entry)
255	
256			if !skipCreateParentDir {
257				dirParts := strings.Split(string(entry.FullPath), "/")
258				if err := f.ensureParentDirectoryEntry(ctx, entry, dirParts, len(dirParts)-1, isFromOtherCluster); err != nil {
259					return err
260				}
261			}
262	
263			glog.V(4).InfofCtx(ctx, "InsertEntry %s: new entry: %v", entry.FullPath, entry.Name())
264			if err := f.Store.InsertEntry(ctx, entry); err != nil {
265				glog.ErrorfCtx(ctx, "insert entry %s: %v", entry.FullPath, err)
266				return fmt.Errorf("insert entry %s: %v", entry.FullPath, err)
267			}
268			if !entry.IsDirectory() {
269				stats.FilerObjectSizeBytesHistogram.Observe(float64(entry.Size()))
270			}
271		} else {
272			if o_excl {
273				glog.V(3).InfofCtx(ctx, "EEXIST: entry %s already exists", entry.FullPath)
274				return fmt.Errorf("%s: %w", entry.FullPath, filer_pb.ErrEntryAlreadyExists)
275			}
276			glog.V(4).InfofCtx(ctx, "UpdateEntry %s: old entry: %v", entry.FullPath, oldEntry.Name())
277			if err := f.UpdateEntry(ctx, oldEntry, entry); err != nil {
278				glog.ErrorfCtx(ctx, "update entry %s: %v", entry.FullPath, err)
279				return fmt.Errorf("update entry %s: %v", entry.FullPath, err)
280			}
281		}
282	
283		f.NotifyUpdateEvent(ctx, oldEntry, entry, true, isFromOtherCluster, signatures)
284	
285		f.deleteChunksIfNotNew(ctx, oldEntry, entry)
286	
287		glog.V(4).InfofCtx(ctx, "CreateEntry %s: created", entry.FullPath)
288	
289		return nil
290	}
