372		lastFileName, err = actualStore.ListDirectoryEntries(ctx, dirPath, startFileName, includeStartFile, limit, func(entry *Entry) (bool, error) {
373			notPrefixed = append(notPrefixed, entry)
374			return true, nil
375		})
376		if err != nil {
377			return
378		}
379	
380		count := int64(0)
381		for count < limit && len(notPrefixed) > 0 {
